import {
  Entity,
  Column,
  PrimaryGeneratedColumn,
  CreateDateColumn,
  Index,
  ManyToOne,
  JoinColumn,
} from 'typeorm';
import { CreditMonitorEnrollment } from './credit-monitor-enrollment.entity';

export type CreditMonitorAlertType =
  | 'score_change'
  | 'new_tradeline'
  | 'closed_tradeline'
  | 'balance_change'
  | 'new_inquiry'
  | 'new_derogatory';

export type CreditMonitorAlertSeverity = 'info' | 'warning' | 'critical';

/**
 * In-app alert generated by the snapshot diff. `payload` is a human-readable
 * summary + before/after numbers — keep it free of account numbers/PII.
 * Delivery is in-app only (no SMS/email until a consent review happens).
 */
@Entity('credit_monitor_alerts')
export class CreditMonitorAlert {
  @PrimaryGeneratedColumn('uuid')
  id: string;

  @Column({ name: 'enrollment_id', type: 'uuid' })
  @Index()
  enrollmentId: string;

  @ManyToOne(() => CreditMonitorEnrollment, { onDelete: 'CASCADE' })
  @JoinColumn({ name: 'enrollment_id' })
  enrollment?: CreditMonitorEnrollment;

  @Column({ type: 'varchar', length: 32 })
  type: CreditMonitorAlertType;

  @Column({ type: 'varchar', length: 16, default: 'info' })
  severity: CreditMonitorAlertSeverity;

  @Column({ type: 'jsonb' })
  payload: {
    summary: string;
    [key: string]: any;
  };

  @Column({ name: 'read_at', type: 'timestamp', nullable: true })
  readAt?: Date;

  @CreateDateColumn({ name: 'created_at' })
  createdAt: Date;
}
